// The vendored elekloader kit (vendor/elekloader/kit) and the catalog Modwerk offers with it (vendor/elekloader/catalog).
// The lock (vendor/elekloader/elekloader.lock.json) pins the kit and the upstream catalog, upstream-catalog.json. Each
// Modwerk-built mod's pins live in its own import record, sdk/imports/elekloader-*.json, so two module PRs never edit
// one shared file. The served catalog/catalog.json is both together: generated by npm ci (prepare) and npm run check,
// never committed. Verifies every pinned file offline, and serves/emits the catalog and its files under elekloader/,
// where the kit's worker loads them. The kit's sources are bundled into the page and the worker through their imports.
import { existsSync, readFileSync, readdirSync, writeFileSync } from 'node:fs'
import { readFile, readdir } from 'node:fs/promises'
import { createHash } from 'node:crypto'
import { dirname, relative, resolve, sep } from 'node:path'
import { fileURLToPath } from 'node:url'
import type { Plugin } from 'vite'
import { parseCatalog, type Catalog } from '../vendor/elekloader/kit/src/kit/catalog.ts'

export const ELEKLOADER_SITE = 'elekloader/'
export const UPSTREAM_CATALOG = 'vendor/elekloader/upstream-catalog.json', SITE_CATALOG = 'vendor/elekloader/catalog/catalog.json'
/** A module's own catalog pins (a repository path), as `npm run elekloader:update -- --overlay` takes them. */
export const isCatalogRecord = (path: string) => /^sdk\/imports\/elekloader-[a-z0-9][a-z0-9.-]*\.json$/.test(path)
type Lock = { schema: number; kind: string; kit: { version: string; protocol: number; files: Record<string, string>; replaced?: Record<string, string> }; catalog: { revision: string; sha256: string } }

/** Kit files Modwerk replaces with its own implementation: each holds a re-export of the module named here, and the
 * lock keeps the upstream file's sha256 under kit.replaced, so an update can say when upstream changed one. */
export const KIT_REPLACEMENTS: Readonly<Record<string, string>> = {
  'src/codec/aplib.ts': 'src/engine/elektron/codec/pack.ts',
  'src/codec/elz.ts': 'src/engine/elektron/codec/depack.ts',
  'src/codec/transport.ts': 'src/engine/elektron/codec/transport.ts',
  'src/isa/coldfire.ts': 'src/engine/elektron/codec/coldfire-kit.ts',
}
/** What a replaced kit file holds: the re-export, relative to vendor/elekloader/kit/<path> unless `from` is given. */
export const replacementText = (path: string, from = '../'.repeat(path.split('/').length + 2) + KIT_REPLACEMENTS[path]) =>
  '// SPDX-License-Identifier: GPL-3.0-or-later\n'
  + '// Modwerk replaces this kit file with its own implementation (vendor/elekloader/README.md, "Replaced kit files").\n'
  + `export * from '${from}'\n`
/** The upstream files the kit's NOTICE credits in its "Code from other projects" section, all ported into the replaced files. */
const REPLACED_ORIGINS = ['elekloader/codec/aplib.py', 'elekloader/codec/elz.py', 'elekloader/codec/transport.py', 'elekloader/isa/coldfire.py']
/** The kit's NOTICE as Modwerk ships it: that section is left out, since its files' code is not included, and a note says
 * which files are replaced. Throws when the section credits any other file, so a new one never loses its notice. */
export function kitNotice(notice: string) {
  const heading = '\nCode from other projects\n------------------------\n', at = notice.indexOf(heading)
  const replaced = Object.keys(KIT_REPLACEMENTS).join(', ')
  const note = `Modwerk ships this kit with ${replaced} replaced by Modwerk's own implementation (vendor/elekloader/README.md).\n\n`
  if (at < 0) return note + notice
  const next = notice.slice(at + heading.length).search(/\n\n[^\n]+\n-{3,}\n/)
  const section = next < 0 ? notice.slice(at + heading.length) : notice.slice(at + heading.length, at + heading.length + next)
  const files = [...section.matchAll(/^ {2}(\S+\.py)\s/gm)].map(match => match[1]).sort()
  if (files.join() !== [...REPLACED_ORIGINS].sort().join())
    throw new Error(`The kit NOTICE's "Code from other projects" section credits ${files.join(', ') || 'no file'}, not exactly the files Modwerk replaces (${REPLACED_ORIGINS.join(', ')}): review it and scripts/elekloader-vendor.ts kitNotice().`)
  return note + notice.slice(0, at).trimEnd() + (next < 0 ? '\n' : notice.slice(at + heading.length + next))
}
type Pin = { file: string; sha256: string; id: string; version: string; device: string; os: string; requires?: string[] }
export type CatalogFile = { schema?: number; kind?: string; about?: string; revision: string; cores: Pin[]; mods: Pin[] }
const sha = (bytes: Uint8Array) => createHash('sha256').update(bytes).digest('hex')

/** Add pinned site-owned package pins without replacing the upstream catalog. */
export function mergeCatalogOverlay(base: CatalogFile, overlay: CatalogFile): CatalogFile {
  parseCatalog(overlay)
  const names = new Map<string, Pin>()
  for (const pin of [...base.cores, ...base.mods]) names.set(pin.file, pin)
  const cores = [...base.cores], mods = [...base.mods]
  const append = (target: Pin[], pins: Pin[]) => {
    for (const pin of pins) {
      const existing = names.get(pin.file)
      if (existing) {
        if (existing.sha256 !== pin.sha256) throw new Error(`Catalog overlay changes the existing file ${pin.file}.`)
        continue
      }
      names.set(pin.file, pin)
      target.push(pin)
    }
  }
  append(cores, overlay.cores)
  append(mods, overlay.mods)
  const merged = { ...base, cores, mods, revision: '' }
  merged.revision = sha(new TextEncoder().encode(JSON.stringify({ schema: merged.schema, kind: merged.kind, cores, mods })))
  parseCatalog(merged)
  return merged
}

/** The served catalog: the upstream catalog plus every module record, in file-name order. `read(path)` gives a
 * repository file's text, or undefined when it is absent, so trusted code can assemble it from Git objects too. */
export function assembleCatalog(read: (path: string) => string | undefined, records: readonly string[]) {
  const upstream = read(UPSTREAM_CATALOG)
  if (upstream === undefined) throw new Error(UPSTREAM_CATALOG + ' is missing')
  const catalog = records.filter(isCatalogRecord).sort()
    .reduce((merged, path) => mergeCatalogOverlay(merged, JSON.parse(read(path)!) as CatalogFile), JSON.parse(upstream) as CatalogFile)
  parseCatalog(catalog)
  return { upstream, catalog, text: JSON.stringify(catalog, null, 1) + '\n' }
}
function siteCatalog(root: string) {
  const imports = resolve(root, 'sdk/imports')
  const records = existsSync(imports) ? readdirSync(imports).map(name => 'sdk/imports/' + name) : []
  return assembleCatalog(path => existsSync(resolve(root, path)) ? readFileSync(resolve(root, path), 'utf8') : undefined, records)
}
/** Writes catalog/catalog.json when it changed. */
export function writeSiteCatalog(root: string) {
  const { text } = siteCatalog(root), target = resolve(root, SITE_CATALOG)
  if (!existsSync(target) || readFileSync(target, 'utf8') !== text) writeFileSync(target, text)
}

async function walk(folder: string): Promise<string[]> {
  const out: string[] = []
  for (const entry of (await readdir(folder, { withFileTypes: true })).sort((a, b) => a.name.localeCompare(b.name))) {
    const path = resolve(folder, entry.name)
    if (entry.isSymbolicLink()) throw new Error('Vendored elekloader must not contain links: ' + path)
    if (entry.isDirectory()) out.push(...await walk(path))
    else out.push(path)
  }
  return out
}
const names = async (folder: string) => (await walk(folder)).map(path => relative(folder, path).split(sep).join('/'))

/** Throws when any vendored byte differs from the lock; -> the lock, the catalog, and the site assets as [path, bytes]. */
export async function readVendoredElekloader(root: string): Promise<{ lock: Lock; catalog: Catalog; assets: [string, Buffer][] }> {
  const folder = resolve(root, 'vendor/elekloader'), kit = resolve(folder, 'kit'), dir = resolve(folder, 'catalog')
  const lock = JSON.parse(await readFile(resolve(folder, 'elekloader.lock.json'), 'utf8')) as Lock
  if (lock.schema !== 1 || lock.kind !== 'elekloader-kit-lock' || !lock.kit?.files || !lock.catalog?.sha256) throw new Error('Invalid elekloader lock file')
  const top = (await readdir(folder)).sort().join(',')
  if (top !== 'README.md,catalog,elekloader.lock.json,kit,upstream-catalog.json') throw new Error('vendor/elekloader holds only README.md, catalog/, elekloader.lock.json, kit/ and upstream-catalog.json: ' + top)
  const bad: string[] = []
  const kitFiles = await names(kit)
  for (const path of kitFiles) if (lock.kit.files[path] !== sha(await readFile(resolve(kit, path)))) bad.push(path in lock.kit.files ? 'kit file changed: ' + path : 'kit file not in the lock: ' + path)
  for (const path of Object.keys(lock.kit.files)) if (!kitFiles.includes(path)) bad.push('kit file missing: ' + path)
  if (Object.keys(lock.kit.replaced ?? {}).sort().join() !== Object.keys(KIT_REPLACEMENTS).sort().join()) bad.push('the lock\'s kit.replaced does not name the kit files Modwerk replaces: ' + Object.keys(KIT_REPLACEMENTS).join(', '))
  for (const path of Object.keys(KIT_REPLACEMENTS))
    if (await readFile(resolve(kit, path), 'utf8').catch(() => '') !== replacementText(path)) bad.push('replaced kit file is not the re-export of ' + KIT_REPLACEMENTS[path] + ': ' + path)
  const site = siteCatalog(root), raw = Buffer.from(site.text)
  if (sha(Buffer.from(site.upstream)) !== lock.catalog.sha256) bad.push('upstream-catalog.json is not the one the lock pins')
  if (!(await readFile(resolve(dir, 'catalog.json')).catch(() => Buffer.alloc(0))).equals(raw)) bad.push('catalog/catalog.json is not the upstream catalog plus the module records: run npm run prepare')
  const catalog = parseCatalog(site.catalog)
  const pins = [...catalog.cores, ...catalog.mods], assets: [string, Buffer][] = [[ELEKLOADER_SITE + 'catalog.json', raw]]
  for (const pin of pins) {
    const data = await readFile(resolve(dir, pin.file)).catch(() => undefined)
    if (!data) bad.push('missing: ' + pin.file)
    else if (sha(data) !== pin.sha256) bad.push('not the pinned file: ' + pin.file)
    else assets.push([ELEKLOADER_SITE + pin.file, data])
  }
  for (const path of await names(dir)) if (path !== 'catalog.json' && !pins.some(pin => pin.file === path)) bad.push('not in the catalog: ' + path)
  if (bad.length) throw new Error('Vendored elekloader differs from its lock:\n' + bad.join('\n'))
  return { lock, catalog, assets }
}

const TYPES: Record<string, string> = { json: 'application/json', elemod: 'application/json' }

/** Serves the verified catalog in development and emits it beside the app in builds. */
export function elekloaderSite(root: string): Plugin {
  let assets: Promise<Map<string, Buffer>> | undefined
  const load = () => assets ??= readVendoredElekloader(root).then(result => new Map(result.assets))
  return {
    name: 'modwerk-elekloader-site',
    configureServer(server) {
      server.middlewares.use(async (request, response, next) => {
        const path = (request.url ?? '').split('?')[0].replace(/^\/+/, '')
        if (!path.startsWith(ELEKLOADER_SITE)) return next()
        const data = (await load()).get(path)
        if (!data) { response.statusCode = 404; response.end(); return }
        response.setHeader('Content-Type', TYPES[path.split('.').pop()!] ?? 'application/octet-stream')
        response.end(data)
      })
    },
    async generateBundle() {
      for (const [fileName, source] of await load()) this.emitFile({ type: 'asset', fileName, source })
    },
  }
}

if (process.argv[1] === fileURLToPath(import.meta.url) && process.argv.includes('--write')) writeSiteCatalog(resolve(dirname(fileURLToPath(import.meta.url)), '..'))
else if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const { lock, catalog, assets } = await readVendoredElekloader(resolve(dirname(fileURLToPath(import.meta.url)), '..'))
  console.log('Vendored elekloader kit ' + lock.kit.version + ' (protocol ' + lock.kit.protocol + ', ' + Object.keys(lock.kit.files).length + ' files) and catalog ' + catalog.revision.slice(0, 7) + ' (' + catalog.cores.length + ' cores, ' + catalog.mods.length + ' mods): ' + assets.length + ' site assets, as the lock pins.')
}
